    check_frozen();fit=check_phase('training');assert fit['all_converged'] and fit['new_primary_fits']==24;assert not (OUT/'scoring_manifest.json').exists();run=manifest('scoring');save(OUT/'scoring_manifest.json',run)
    obs,price,returns=data();base=csv('classification_baselines');sources={s['job']:s for s in read(OUT/'source_heads.json')};forecasts=[];components=[];summaries=[]
